// MyS_Front\src\paginas\perfil\Perfil.jsx

import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import MainLayout from "../../components/Layout";
import ComentarioFlotante from "../../ventanas/ComentarioFlotante";
import "./Perfil.css";
import {
    getPublicacionesPorPerfil,
    getComentariosPorPublicacion,
    getComentariosPorPerfil,
    darLikePublicacion,
    darLikeComentario,
    crearComentario,
    estaAutenticado,
    getUsuarioActual,
    logout
} from "../../Api";

const Perfil = () => {
    const navigate = useNavigate();
    
    const [usuario, setUsuario] = useState(null);
    const [perfil, setPerfil] = useState(null);
    const [posts, setPosts] = useState([]);
    const [comentariosPorPost, setComentariosPorPost] = useState({});
    const [clickedKudos, setClickedKudos] = useState(null);
    const [comentarioVisibleId, setComentarioVisibleId] = useState(null);
    const [mostrarComentariosDePost, setMostrarComentariosDePost] = useState({});
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [publicacionesConComentarios, setPublicacionesConComentarios] = useState([]);
    
    // ✅ EFECTO: Verificar autenticación (solo al montar)
    useEffect(() => {
        const usuarioLogeado = getUsuarioActual();
        console.log("👤 Usuario logeado:", usuarioLogeado);
        
        if (!usuarioLogeado || !usuarioLogeado.perfil) {
            console.log("❌ No hay usuario logeado o perfil, redirigiendo a /cuenta");
            navigate("/cuenta");
            return;
        }
        
        setUsuario(usuarioLogeado);
        setPerfil(usuarioLogeado.perfil);
        
        console.log("✅ Perfil cargado:", usuarioLogeado.perfil);
    }, [navigate]);
    
    // ✅ EFECTO: Cargar publicaciones (solo cuando perfil cambia)
    useEffect(() => {
        if (!perfil || !perfil.id) {
            return;
        }
        
        cargarPublicacionesDelPerfil();
        cargarComentariosDelPerfil();
    }, [perfil?.id]);
    
    // Cargar comentarios que el perfil hizo en otras publicaciones
    const cargarComentariosDelPerfil = async () => {
        if (!perfil || !perfil.id) {
            console.error("❌ No hay perfil válido");
            return;
        }
        
        try {
            console.log("💬 Cargando comentarios del PERFIL ID:", perfil.id);
            
            const data = await getComentariosPorPerfil(perfil.id);
            
            console.log(`✅ ${data.length} comentarios del perfil cargados`);
            
            // Agrupar comentarios por publicación
            const publicacionesMap = new Map();
            
            data.forEach(comentario => {
                const pubInfo = comentario.publicacion_info;
                
                if (!pubInfo) return;
                
                if (!publicacionesMap.has(pubInfo.id)) {
                    publicacionesMap.set(pubInfo.id, {
                        id: pubInfo.id,
                        perfilId: pubInfo.perfil,
                        author: pubInfo.perfil_info?.nom_usuario || "Usuario",
                        avatar: pubInfo.perfil_info?.foto_perfil || "/default-avatar.png",
                        date: new Date(pubInfo.fecha_pub).toLocaleString("es-MX", {
                            year: "numeric",
                            month: "2-digit",
                            day: "2-digit",
                            hour: "2-digit",
                            minute: "2-digit",
                        }),
                        content: pubInfo.texto,
                        image: null,
                        kudos: pubInfo.like_pub,
                        esComentarioAjeno: true,
                        comentariosDelPerfil: []
                    });
                }
                
                publicacionesMap.get(pubInfo.id).comentariosDelPerfil.push({
                    id: comentario.id,
                    author: perfil.nom_usuario,
                    avatar: perfil.foto_perfil || "/default-avatar.png",
                    text: comentario.texto,
                    kudos: comentario.like_com,
                    fecha: new Date(comentario.fecha_com).toLocaleString("es-MX"),
                });
            });
            
            const publicacionesConComentariosArray = Array.from(publicacionesMap.values());
            
            console.log("📋 Publicaciones con comentarios:", publicacionesConComentariosArray);
            
            setPublicacionesConComentarios(publicacionesConComentariosArray);
            
            // Mostrar comentarios por defecto
            const visibles = {};
            publicacionesConComentariosArray.forEach(pub => {
                visibles[pub.id] = true;
            });
            setMostrarComentariosDePost(prev => ({ ...prev, ...visibles }));
            
        } catch (err) {
            console.error("❌ Error al cargar comentarios del perfil:", err);
        }
    };
    
    // Cargar publicaciones del PERFIL desde la API
    const cargarPublicacionesDelPerfil = async () => {
        if (!perfil || !perfil.id) {
            console.error("❌ No hay perfil válido");
            return;
        }
        
        try {
            setLoading(true);
            setError(null);
            
            console.log("📥 Cargando publicaciones del PERFIL ID:", perfil.id);
            console.log("📝 Nombre del perfil:", perfil.nom_usuario);
            
            const data = await getPublicacionesPorPerfil(perfil.id);
            
            const publicaciones = Array.isArray(data)
                ? data
                : Array.isArray(data.results)
                    ? data.results
                    : [];
            
            console.log(`✅ ${publicaciones.length} publicaciones cargadas del perfil`);
            
            const publicacionesFormateadas = publicaciones.map(pub => ({
                id: pub.id,
                perfilId: pub.perfil,
                author: perfil.nom_usuario,
                avatar: perfil.foto_perfil || "/default-avatar.png",
                date: new Date(pub.fecha_pub).toLocaleString("es-MX", {
                    year: "numeric",
                    month: "2-digit",
                    day: "2-digit",
                    hour: "2-digit",
                    minute: "2-digit",
                }),
                content: pub.texto,
                image: pub.fotos && pub.fotos.length > 0 ? pub.fotos[0].ruta_foto : null,
                kudos: pub.like_pub,
            }));
            
            setPosts(publicacionesFormateadas);
            
            // Cargar comentarios de todas las publicaciones
            if (publicacionesFormateadas.length > 0) {
                await cargarTodosLosComentarios(publicacionesFormateadas);
            }
        } catch (err) {
            console.error("❌ Error al cargar publicaciones:", err);
            setError("No se pudieron cargar las publicaciones");
        } finally {
            setLoading(false);
        }
    };
    
    // Cargar comentarios de todas las publicaciones
    const cargarTodosLosComentarios = async (publicaciones) => {
        try {
            const comentariosPromises = publicaciones.map(post => cargarComentarios(post.id));
            await Promise.all(comentariosPromises);
            
            // Mostrar todos los comentarios por defecto
            const todosVisibles = {};
            publicaciones.forEach(post => {
                todosVisibles[post.id] = true;
            });
            setMostrarComentariosDePost(prev => ({ ...prev, ...todosVisibles }));
        } catch (err) {
            console.error("❌ Error al cargar comentarios:", err);
        }
    };
    
    // Cargar comentarios de un post específico
    const cargarComentarios = async (postId) => {
        if (comentariosPorPost[postId]) {
            return;
        }
        
        try {
            console.log(`📥 Cargando comentarios para post ${postId}...`);
            const comentarios = await getComentariosPorPublicacion(postId);
            
            const comentariosFormateados = comentarios.map(com => ({
                id: com.id,
                author: com.perfil_info?.nom_usuario || "Usuario",
                avatar: com.perfil_info?.foto_perfil || "/default-avatar.png",
                text: com.texto,
                kudos: com.like_com,
                fecha: new Date(com.fecha_com).toLocaleString("es-MX"),
            }));
            
            setComentariosPorPost(prev => ({
                ...prev,
                [postId]: comentariosFormateados
            }));
        } catch (err) {
            console.error("❌ Error al cargar comentarios:", err);
        }
    };
    
    // Toggle para mostrar/ocultar comentarios
    const toggleMostrarComentarios = async (postId) => {
        if (mostrarComentariosDePost[postId]) {
            setMostrarComentariosDePost(prev => ({
                ...prev,
                [postId]: false
            }));
        } else {
            setMostrarComentariosDePost(prev => ({
                ...prev,
                [postId]: true
            }));
            
            if (!comentariosPorPost[postId]) {
                await cargarComentarios(postId);
            }
        }
    };
    
    // Manejar kudos en posts
    const handleKudosClick = async (postId) => {
        if (!estaAutenticado()) {
            alert("Debes iniciar sesión para dar kudos");
            return;
        }
        
        try {
            const result = await darLikePublicacion(postId);
            setPosts(prev => prev.map(post => 
                post.id === postId ? { ...post, kudos: result.likes } : post
            ));
            
            setClickedKudos(postId);
            setTimeout(() => setClickedKudos(null), 300);
        } catch (err) {
            console.error("❌ Error al dar kudos:", err);
            if (err.message.includes("autenticado")) {
                alert("Tu sesión expiró. Por favor inicia sesión nuevamente.");
            }
        }
    };
    
    // Manejar kudos en comentarios
    const handleComentarioKudosClick = async (comentarioId, postId) => {
        if (!estaAutenticado()) {
            alert("Debes iniciar sesión para dar kudos");
            return;
        }
        
        try {
            const result = await darLikeComentario(comentarioId);
            setComentariosPorPost(prev => {
                if (!prev[postId]) return prev;
                
                return {
                    ...prev,
                    [postId]: prev[postId].map(com =>
                        com.id === comentarioId ? { ...com, kudos: result.likes } : com
                    )
                };
            });
            
            setClickedKudos(comentarioId);
            setTimeout(() => setClickedKudos(null), 300);
        } catch (err) {
            console.error("❌ Error al dar kudos:", err);
            if (err.message.includes("autenticado")) {
                alert("Tu sesión expiró. Por favor inicia sesión nuevamente.");
            }
        }
    };
    
    // Toggle ventana de comentarios
    const toggleComentario = (postId) => {
        setComentarioVisibleId(prev => (prev === postId ? null : postId));
    };
    
    // Agregar comentario usando el PERFIL
    const handleAgregarComentario = async (postId, texto) => {
        if (!estaAutenticado() || !perfil) {
            alert("Debes iniciar sesión para comentar");
            return;
        }
        
        try {
            console.log("💬 Creando comentario desde perfil:", perfil.nom_usuario);
            
            const comentarioData = {
                texto: texto,
                publicacion: postId,
                perfil: perfil.id
            };
            
            const resultado = await crearComentario(comentarioData);
            
            const nuevoComentario = {
                id: resultado.id,
                author: perfil.nom_usuario,
                avatar: perfil.foto_perfil || "/default-avatar.png",
                text: texto,
                kudos: 0,
                fecha: new Date().toLocaleString("es-MX"),
            };
            
            setComentariosPorPost(prev => ({
                ...prev,
                [postId]: [...(prev[postId] || []), nuevoComentario]
            }));
            
            setMostrarComentariosDePost(prev => ({
                ...prev,
                [postId]: true
            }));
            
            setComentarioVisibleId(null);
        } catch (err) {
            console.error("❌ Error al crear comentario:", err);
            alert(`Error al crear el comentario: ${err.message}`);
        }
    };
    
    // Función para cerrar sesión
    const handleCerrarSesion = async () => {
        try {
            await logout();
            navigate("/cuenta");
        } catch (error) {
            console.error("❌ Error al cerrar sesión:", error);
            localStorage.removeItem("usuarioLogeado");
            navigate("/cuenta");
        }
    };
    
    // Si no hay perfil, mostrar loading
    if (!perfil) {
        return (
            <MainLayout tituloPagina="Perfil" gridClass="perfil-grid">
                <div className="perfil-loading">
                    <p>Cargando perfil...</p>
                </div>
            </MainLayout>
        );
    }
    
    return (
        <MainLayout tituloPagina="Perfil" gridClass="perfil-grid">
            {/* CONTENIDO DEL PERFIL */}
            <div className="perfil-main-content">
                {/* Imagen y descripción de perfil */}
                <div className="perfil-header">
                    <div className="perfil-main-ima-perf">
                        <img 
                            src={perfil.foto_perfil || "/default-avatar.png"} 
                            alt="Imagen de perfil" 
                        />
                    </div>
                    <div className="perfil-descrip-perf">
                        <h2>{perfil.nom_usuario}</h2>
                        <p>{perfil.perfil_info || "Sin descripción"}</p>
                        <div style={{ marginTop: '10px', fontSize: '12px', color: '#666' }}>
                            <p>📧 Usuario: {usuario?.usuario?.correo}</p>
                        </div>
                        <button 
                            onClick={handleCerrarSesion}
                            style={{
                                marginTop: '10px',
                                padding: '5px 15px',
                                backgroundColor: '#ff4444',
                                color: 'white',
                                border: 'none',
                                borderRadius: '5px',
                                cursor: 'pointer'
                            }}
                        >
                            Cerrar Sesión
                        </button>
                    </div>
                </div>
                
                {/* Sección de posts */}
                <div className="perfil-main-blog">
                    <hr />
                    <div className="perfil-blog-area">
                        {/* Navbar de opciones */}
                        <div className="perfil-main-navbar">
                            <div className="perfil-navbar-left">
                                <ul className="perfil-navbar-ul">
                                    <li><button>[Hashtags]</button></li>
                                    <li><button>[Imágenes]</button></li>
                                </ul>
                            </div>
                            <div className="perfil-navbar-right">
                                <ul className="perfil-mod">
                                    <li>
                                        <a href="/editar" title="Editar perfil">
                                            <i className="bi bi-pencil-square"></i>
                                        </a>
                                    </li>
                                </ul>
                            </div>
                        </div>
                        
                        {/* Lista de posts */}
                        <div className="perfil-all-post">
                            {loading ? (
                                <div className="perfil-sin-posts">
                                    <p>Cargando publicaciones...</p>
                                </div>
                            ) : error ? (
                                <div className="perfil-sin-posts" style={{ color: 'red' }}>
                                    <p>{error}</p>
                                </div>
                            ) : posts.length === 0 && publicacionesConComentarios.length === 0 ? (
                                <div className="perfil-sin-posts">
                                    <p>No has publicado ni comentado nada aún</p>
                                </div>
                            ) : (
                                <>
                                    {/* Publicaciones propias del perfil */}
                                    {posts.map(post => (
                                        <div key={post.id} className="perfil-blog-post">
                                            <div className="perfil-post-perf">
                                                {/* Información del autor (PERFIL) */}
                                                <div className="perfil-info-main">
                                                    <img 
                                                        className="perfil-ima-inf" 
                                                        src={post.avatar} 
                                                        alt="foto perfil" 
                                                    />
                                                    <h6 className="perfil-nombre">{post.author}</h6>
                                                    <h6 className="perfil-public">Publicó</h6>
                                                    <h6 className="perfil-fecha">{post.date}</h6>
                                                    <div className="perfil-opciones-botton">
                                                        <button
                                                            className="perfil-crear-coment"
                                                            onClick={() => toggleComentario(post.id)}
                                                        >
                                                            <i className="bi bi-caret-right-fill"></i>
                                                        </button>
                                                        {comentarioVisibleId === post.id && (
                                                            <ComentarioFlotante
                                                                onClose={() => setComentarioVisibleId(null)}
                                                                onSubmit={texto => handleAgregarComentario(post.id, texto)}
                                                            />
                                                        )}
                                                    </div>
                                                </div>
                                                
                                                {/* Contenido del post */}
                                                <div className="perfil-post">
                                                    <p>{post.content}</p>
                                                </div>
                                                
                                                {/* Imagen del post */}
                                                {post.image && (
                                                    <div className="perfil-post-ima">
                                                        <img 
                                                            className="perfil-ima-pub" 
                                                            src={post.image} 
                                                            alt="imagen-post" 
                                                        />
                                                    </div>
                                                )}
                                                
                                                {/* Botones de interacción */}
                                                <div className="perfil-opciones-botton">
                                                    <button className="perfil-check" type="button">
                                                        [check]
                                                    </button>
                                                    <button
                                                        className={`perfil-kudos ${clickedKudos === post.id ? 'clicked' : ''}`}
                                                        onClick={() => handleKudosClick(post.id)}
                                                        title={`${post.kudos || 0} kudos`}
                                                    >
                                                        <i className="bi bi-bug-fill"></i>
                                                    </button>
                                                    <button
                                                        className="perfil-ver-comentarios"
                                                        onClick={() => toggleMostrarComentarios(post.id)}
                                                        type="button"
                                                    >
                                                        {mostrarComentariosDePost[post.id] ? '[-] Ocultar' : '[+] Ver'} comentarios
                                                    </button>
                                                </div>
                                            </div>
                                            
                                            {/* Comentarios del post */}
                                            {mostrarComentariosDePost[post.id] && comentariosPorPost[post.id] && comentariosPorPost[post.id].length > 0 && (
                                                <div className="perfil-comentarios-lista">
                                                    {comentariosPorPost[post.id].map(c => (
                                                        <div key={c.id} className="perfil-comentario-item">
                                                            <div className="perfil-comentario-header">
                                                                <img 
                                                                    className="perfil-comentario-avatar" 
                                                                    src={c.avatar} 
                                                                    alt={`Avatar de ${c.author}`}
                                                                />
                                                                <div className="perfil-comentario-info">
                                                                    <span className="perfil-comentario-autor">
                                                                        {c.author}
                                                                    </span>
                                                                    <span className="perfil-comentario-texto">
                                                                        {" "}respondió
                                                                    </span>
                                                                </div>
                                                            </div>
                                                            <div className="perfil-comentario-contenido">
                                                                <p>{c.text}</p>
                                                            </div>
                                                            <div className="perfil-opciones-comentario">
                                                                <button 
                                                                    className="perfil-check-comentario" 
                                                                    type="button"
                                                                >
                                                                    [check]
                                                                </button>
                                                                <button
                                                                    className={`perfil-kudos-comentario ${clickedKudos === c.id ? 'clicked' : ''}`}
                                                                    onClick={() => handleComentarioKudosClick(c.id, post.id)}
                                                                    title={`${c.kudos || 0} kudos`}
                                                                >
                                                                    <i className="bi bi-bug-fill"></i>
                                                                </button>
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                    
                                    {/* ✅ Publicaciones donde el perfil comentó */}
                                    {publicacionesConComentarios.map(post => (
                                        <div key={`comentario-${post.id}`} className="perfil-blog-post" style={{ borderLeft: '3px solid #4CAF50' }}>
                                            <div className="perfil-post-perf">
                                                {/* Información del autor ORIGINAL de la publicación */}
                                                <div className="perfil-info-main">
                                                    <img 
                                                        className="perfil-ima-inf" 
                                                        src={post.avatar} 
                                                        alt="foto perfil" 
                                                    />
                                                    <h6 className="perfil-nombre">{post.author}</h6>
                                                    <h6 className="perfil-public">Publicó</h6>
                                                    <h6 className="perfil-fecha">{post.date}</h6>
                                                </div>
                                                
                                                {/* Contenido del post ORIGINAL */}
                                                <div className="perfil-post">
                                                    <p>{post.content}</p>
                                                </div>
                                                
                                                {/* Imagen del post */}
                                                {post.image && (
                                                    <div className="perfil-post-ima">
                                                        <img 
                                                            className="perfil-ima-pub" 
                                                            src={post.image} 
                                                            alt="imagen-post" 
                                                        />
                                                    </div>
                                                )}
                                                
                                                {/* Botones de interacción */}
                                                <div className="perfil-opciones-botton">
                                                    <button className="perfil-check" type="button">
                                                        [check]
                                                    </button>
                                                    <button
                                                        className={`perfil-kudos ${clickedKudos === post.id ? 'clicked' : ''}`}
                                                        onClick={() => handleKudosClick(post.id)}
                                                        title={`${post.kudos || 0} kudos`}
                                                    >
                                                        <i className="bi bi-bug-fill"></i>
                                                    </button>
                                                    <button
                                                        className="perfil-ver-comentarios"
                                                        onClick={() => toggleMostrarComentarios(post.id)}
                                                        type="button"
                                                    >
                                                        {mostrarComentariosDePost[post.id] ? '[-] Ocultar' : '[+] Ver'} tus comentarios
                                                    </button>
                                                </div>
                                            </div>
                                            
                                            {/* Comentarios DEL PERFIL en esta publicación */}
                                            {mostrarComentariosDePost[post.id] && post.comentariosDelPerfil && post.comentariosDelPerfil.length > 0 && (
                                                <div className="perfil-comentarios-lista">
                                                    {post.comentariosDelPerfil.map(c => (
                                                        <div key={`c-${c.id}`} className="perfil-comentario-item" style={{ backgroundColor: '#f0f8ff' }}>
                                                            <div className="perfil-comentario-header">
                                                                <img 
                                                                    className="perfil-comentario-avatar" 
                                                                    src={c.avatar} 
                                                                    alt={`Avatar de ${c.author}`}
                                                                />
                                                                <div className="perfil-comentario-info">
                                                                    <span className="perfil-comentario-autor">
                                                                        {c.author}
                                                                    </span>
                                                                    <span className="perfil-comentario-texto">
                                                                        {" "}comentó
                                                                    </span>
                                                                </div>
                                                            </div>
                                                            <div className="perfil-comentario-contenido">
                                                                <p>{c.text}</p>
                                                            </div>
                                                            <div className="perfil-opciones-comentario">
                                                                <button 
                                                                    className="perfil-check-comentario" 
                                                                    type="button"
                                                                >
                                                                    [check]
                                                                </button>
                                                                <button
                                                                    className={`perfil-kudos-comentario ${clickedKudos === c.id ? 'clicked' : ''}`}
                                                                    onClick={() => handleComentarioKudosClick(c.id, post.id)}
                                                                    title={`${c.kudos || 0} kudos`}
                                                                >
                                                                    <i className="bi bi-bug-fill"></i>
                                                                </button>
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    ))}
                                </>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </MainLayout>
    );
};

export default Perfil;
